let db=null,view='home',subject='',group='',period='',activity='',student='',draft=null,draftBaseline='',reviewFilter='',reviewFilterActivity='',criterionIndex=0,ix=null,profileId=null,saveQueue=Promise.resolve(),modalCleanup=null;
const fmt=x=>x===null||x===undefined?'—':String(x),nowDate=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')},ev=()=>db.subjects.find(x=>x.id===subject)?.evaluation||Aula.evaluation();
