function activities(){return list('activities').filter(a=>a.groupId===group&&a.periodId===period)}
function inCurrentRoster(s){const g=db.groups.find(g=>g.id===s.groupId),key=Aula.idKey(s.number,db.settings.idMatching);return s.enrollmentStatus!=='baja'&&!s.participationInactive&&!s.rosterMissing&&!g?.excludedRosterIDs?.includes(key)&&(!g?.listaRosterIDs||g.listaRosterIDs.includes(key))}
