function matchesStudentSearch(s,q){const key=Aula.idKey(q,db.settings.idMatching);return Aula.norm([s.name,s.number,s.originalNumber||'',s.moodleIdentity?.number||''].join(' ')).includes(q)||!!key&&Aula.idKey(s.number,db.settings.idMatching).includes(key)}
