async function mutate(change,message='Guardado'){const task=saveQueue.then(async()=>{const cloud=typeof ProfeCloud!=='undefined'&&(ProfeCloud.active()||window.PROFEFLOW_CLOUD?.requireLogin);if(uncertainMutation&&!ProfeCloud.hasPending())uncertainMutation=null;const context=mutationContext();if(uncertainMutation&&uncertainMutation.context!==context)throw Error('Hay un guardado anterior sin confirmar. Conservamos tu captura. Usa Mi cuenta → Verificar / reintentar guardado pendiente antes de enviar otros cambios.');const next=uncertainMutation?.next||Aula.clone(db),expected=uncertainMutation?.expected??db.revision;if(!uncertainMutation){await change(next);Aula.applyIdFormat(next);Aula.validate(next)}$('saveStatus').textContent=cloud?'Guardando en la nube':'Guardando…';try{const result=await AulaStorage.write(next,expected);uncertainMutation=null;db=result;ix=Aula.index(db);$('saveStatus').textContent=cloud?'Se confirmó el guardado en la nube':'Guardado · '+AulaStorage.mode;return true}catch(e){if(cloud&&ProfeCloud.hasPending())uncertainMutation={next,expected,context};$('saveStatus').textContent=cloud?e.message:'No guardado';throw e}});saveQueue=task.catch(()=>{});await task;if(message&&!$('modal').open)toast(message);return true}
